import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api';
import { Line, Bar } from 'react-chartjs-2';
import { Activity } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend
);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await getFiles();
        setFiles(res.data || []);
      } catch {}
    };
    load();
  }, []);

  // ================= SAFE METRIC ACCESS =================
  const getTotal = (f) => f?.metrics?.total_ms ?? f?.metrics?.total ?? 0;

  // ================= LABELS (FILE NAMES) =================
  const labels = files.map(f => f.filename);

  // ================= DATASETS =================
  const pqcData = files.map(f =>
    f.mode === 'hybrid' ? getTotal(f) : null
  );

  const rsaData = files.map(f =>
    f.mode !== 'hybrid' ? getTotal(f) : null
  );

  // ================= AVERAGES =================
  const hybrid = files.filter(f => f.mode === 'hybrid');
  const rsa = files.filter(f => f.mode !== 'hybrid');

  const avgPqc = hybrid.length
    ? (hybrid.reduce((a, f) => a + getTotal(f), 0) / hybrid.length).toFixed(2)
    : "0.00";

  const avgRsa = rsa.length
    ? (rsa.reduce((a, f) => a + getTotal(f), 0) / rsa.length).toFixed(2)
    : "0.00";

  // ================= TIMELINE =================
  const lineChartData = {
    labels,
    datasets: [
      {
        label: 'Hybrid (X25519)',
        data: pqcData,
        borderColor: '#00ff9d',
        backgroundColor: '#00ff9d',
        borderWidth: 2,
        tension: 0.4,
        spanGaps: true
      },
      {
        label: 'RSA Baseline',
        data: rsaData,
        borderColor: '#a855f7',
        backgroundColor: '#a855f7',
        borderWidth: 2,
        tension: 0.4,
        spanGaps: true
      }
    ]
  };

  const comparisonData = {
    labels: ['Average'],
    datasets: [
      { label: 'Hybrid', data: [avgPqc], backgroundColor: '#00ff9d' },
      { label: 'RSA', data: [avgRsa], backgroundColor: '#a855f7' }
    ]
  };

  return (
    <div className="p-8 h-full space-y-6 overflow-y-auto custom-scrollbar">
      
      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <div>
          <h2 className="text-2xl font-bold text-white tracking-wide">
            Performance Monitor
          </h2>
          <p className="text-gray-500 text-xs font-mono uppercase">
            Comparative Analysis Engine
          </p>
        </div>

        <div className="text-right">
          <span className="text-xs text-gray-500 uppercase">Total Files</span>
          <p className="text-2xl font-mono text-white">{files.length}</p>
        </div>
      </div>

      {/* ================= GRAPH SECTION ================= */}
      <div className="grid grid-cols-3 gap-6">

        {/* Timeline */}
        <div className="col-span-2 bg-scifi-panel border border-scifi-border p-6 rounded-xl">
          <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-6 flex items-center gap-2">
            <Activity size={16} className="text-neon-blue" />
            Encryption Latency Timeline
          </h3>

          <div className="h-72">
            <Line
              data={lineChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: {
                    labels: { color: '#fff', font: { size: 10 } }
                  }
                },
                scales: {
                  y: { grid: { color: '#222' } },
                  x: { grid: { display: false } }
                }
              }}
            />
          </div>
        </div>

        {/* Averages */}
        <div className="col-span-1 space-y-6">
          <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl h-48">
            <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-4">
              Mean Latency
            </h3>

            <div className="h-32">
              <Bar
                data={comparisonData}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: { legend: { display: false } },
                  scales: { x: { display: false }, y: { grid: { color: '#222' } } }
                }}
              />
            </div>
          </div>

          <div className="bg-black/40 border border-gray-800 p-4 rounded flex justify-between">
            <span className="text-xs text-gray-500 uppercase">Avg Hybrid</span>
            <span className="text-neon-green font-mono font-bold">
              {avgPqc} ms
            </span>
          </div>

          <div className="bg-black/40 border border-gray-800 p-4 rounded flex justify-between">
            <span className="text-xs text-gray-500 uppercase">Avg RSA</span>
            <span className="text-purple-400 font-mono font-bold">
              {avgRsa} ms
            </span>
          </div>
        </div>
      </div>

      {/* ================= PER FILE CARDS ================= */}
      <div className="space-y-3">
        {files.map(file => (
          <div key={file.id} className="bg-black/40 border border-gray-800 p-4 rounded">
            <div className="flex justify-between mb-2">
              <span className="text-white font-bold">{file.filename}</span>
              <span className={file.mode === 'hybrid' ? 'text-neon-green' : 'text-purple-400'}>
                {file.mode}
              </span>
            </div>

            <div className="text-xs font-mono text-gray-400">
              Total: <span className="text-white">{getTotal(file)} ms</span>
            </div>
          </div>
        ))}
      </div>

    </div>
  );
};

export default Performance;
